document.addEventListener("click",async e=>{const r=e.target.closest("a[data-al-load-more]");if(!r||e.button!==0||e.metaKey||e.ctrlKey||e.shiftKey||e.altKey)return;const t=r.closest("[data-al-listing]");if(!t||t.getAttribute("aria-busy")==="true")return;e.preventDefault(),t.setAttribute("aria-busy","true");const a=t.querySelector(".al-listing__status"),n=new AbortController,d=setTimeout(()=>n.abort(),15e3);try{const i=await fetch(r.href,{signal:n.signal});if(!i.ok)throw new Error("Response failed");const s=[...new DOMParser().parseFromString(await i.text(),"text/html").querySelectorAll("[data-al-listing]")].find(y=>y.dataset.alListing===t.dataset.alListing),o=s?.querySelector(".al-listing__items");if(!o||!o.children.length)throw new Error("Missing content");const l=[...o.children];t.querySelector(".al-listing__items").append(...l);const c=t.querySelector(".al-pagination"),u=s.querySelector(".al-pagination");u?c.replaceWith(u):c.remove(),l[0].querySelector('a:not([aria-hidden="true"])')?.focus({preventScroll:!0}),a.textContent=a.dataset.loaded}catch{a.textContent=a.dataset.error,r.removeAttribute("data-al-load-more")}finally{clearTimeout(d),t.removeAttribute("aria-busy")}});
